import{z as A,x as B,o as t,c as p,q as n,j as i,D as r,d as E,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"风险调整比率的抽样误差","description":"","frontmatter":{"title":"风险调整比率的抽样误差","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ratio-sampling-error.md","filePath":"quant/ratio-sampling-error.md","lastUpdated":1791413859000}'),d={name:"quant/ratio-sampling-error.md"};function m(h,a,u,D,f,F){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="风险调整比率的抽样误差" tabindex="-1">风险调整比率的抽样误差 <a class="header-anchor" href="#风险调整比率的抽样误差" aria-label="Permalink to &quot;风险调整比率的抽样误差&quot;">​</a></h1><div class="epigraph"><p>夏普是均值除以标准差；均值在短样本上几乎估不准，于是小数点后两位的 IR 排序往往没有统计内容。</p><footer>—— Merton, On Estimating the Expected Return on the Market, Journal of Financial Economics, 1980；夏普的抽样理论见 Lo, Financial Analysts Journal, 2002</footer></div><p><a href="/quant/trade-level-attribution">上一课</a>把 P&amp;L 拆清了。本课的缺口是<strong>清过的账仍然是短样本</strong>：<a href="/quant/ir-sharpe">IR/Sharpe</a> 的点估计方差很大。Merton（1980）说明：估计预期收益需要极长的日历时间，提高采样频率帮不上均值。Lo（2002）给出夏普在序列相关下的分布。Jobson–Korkie 讨论两基金夏普之差的检验。<a href="/quant/deflated-sharpe">放气夏普</a> 与 <a href="/quant/probabilistic-sharpe">概率夏普</a> 把选择偏差叠加上去。本课收口业绩单元：比率是估计量，不是标签。下一课程从 <a href="/quant/matching-engine-arch">撮合引擎</a> 起，解释这些收益里的成交在系统里如何被排程——没有引擎时间戳，连「一笔交易」的定义都会漂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>年化夏普 \\(\\hat{\\mathrm{SR}}=\\bar x/s_x\\sqrt{q}\\)。\\(\\bar x\\) 的误差是 \\(\\sigma/\\sqrt{T_{\\mathrm{年}}}\\) 量级，与日内格子密度几乎无关。三年月频、夏普 1.0，置信区间可以跨过 0。Sortino 只用下行观测，更噪。问题是比较：基金 A 夏普 1.1、B 夏普 0.9，在合理 \\(T\\) 与相关下经常不可区分。把地图上每一类策略按样本夏普排名，再据此加杠杆，是用噪声做风险预算。</p><p><span class="marginnote">代个数感受误差有多大：三年月频（\\(T=3\\) 年）、夏普 1.0 时，年化夏普的标准误约为 \\(\\sqrt{(1+1.0^2/2)/3}\\approx 0.7\\)，九五置信区间大约从 \\(-0.4\\) 到 \\(2.4\\)——「夏普 1.0」这个点估计，其实和零乃至和 2 都分不开。</span></p><p>与费用、流：扣费与 MWR 改变的是点估计的中心，不缩小抽样方差。技能若有，仍要过「估计误差 + 选择偏差」两关。</p><h3 id="相关与重叠" tabindex="-1">相关与重叠 <a class="header-anchor" href="#相关与重叠" aria-label="Permalink to &quot;相关与重叠&quot;">​</a></h3><p>多只基金暴露同一 ARP 时，夏普之差的方差不含「独立样本」那么小。策略桶之间的相关升（危机）让「分散的 IR」不可加。长地平重叠收益的标准误见主干重叠课，此处只提醒：用同一段市场路径评价所有产品，有效 \\(T\\) 是一段牛熊，不是产品个数。</p><p><span class="marginnote">提高日频只改善 \\(\\sigma\\) 的估计，几乎不改善 \\(\\mu\\)。把日频夏普报成三位小数，是对 Merton 1980 的忽视。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告：点估计 + Lo 调整的标准误或置信区间；PSR/DSR 对 \\(N\\) 次试验。比较：Jobson–Korkie 或 bootstrap 两样本。预注册评价窗口。杠杆前先看区间是否不含零，而不是看点估计是否大于 1。对短波动等非对称策略，夏普尤其误导，应并报缺口月。</p>',12)),(t(),i(l,null,{default:r(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9F%BA%E9%87%91%20A%20%E5%A4%8F%E6%99%AE%201.1%22%5D%20--%3E%20DIFF%5B%22%E5%B7%AE%200.2%22%5D%0A%20%20B%5B%22%E5%9F%BA%E9%87%91%20B%20%E5%A4%8F%E6%99%AE%200.9%22%5D%20--%3E%20DIFF%0A%20%20DIFF%20--%3E%20SE%5B%22%E7%AE%97%E5%B7%AE%E7%9A%84%E6%A0%87%E5%87%86%E8%AF%AF%20JK%20%E6%88%96%20bootstrap%22%5D%0A%20%20SE%20--%3E%20Q%7B%22%E5%8C%BA%E9%97%B4%E5%90%AB%E9%9B%B6%E5%90%97%22%7D%0A%20%20Q%20--%20%22%E5%90%AB%E9%9B%B6%22%20--%3E%20TIE%5B%22%E7%BB%9F%E8%AE%A1%E4%B8%8A%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%EF%BC%8C%E5%8B%BF%E6%8C%89%E6%8E%92%E5%90%8D%E5%8A%A0%E6%9D%A0%E6%9D%86%22%5D%0A%20%20Q%20--%20%22%E4%B8%8D%E5%90%AB%E9%9B%B6%22%20--%3E%20DSR%5B%22%E8%BF%98%E8%A6%81%E8%BF%87%E8%AF%95%E9%AA%8C%E6%AC%A1%E6%95%B0%E6%94%BE%E6%B0%94%E5%85%B3%22%5D%0A%20%20DSR%20--%3E%20OK%5B%22%E6%89%8D%E8%B0%88%E5%BE%97%E4%B8%8A%E9%80%89%20A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"Jobson–Korkie 检验翻译一下：专门回答「A 的夏普真比 B 高吗」。把两只夏普之差除以这个差自身的标准误，得到近似标准正态的统计量；两基金收益相关性越高，差的标准误越大，越难分出高下——同一市场里的多策略尤其如此。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"比率的分子是漂移，分母是波动。扩散里，漂移的信息随日历时间累积，波动的信息随采样累积。于是「高夏普」在短样本上大量是运气。选择偏差再把运气的上分位当成产品。业绩单元能做的是把会计做对、把误差报出来；不能把噪声变成技能。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：把采样从月频加密到日频就能让夏普「更准」。Merton 指出这几乎只改善波动 \\(\\sigma\\) 的估计；均值 \\(\\mu\\) 的误差按日历年数以 \\(1/\\sqrt{T}\\) 缩慢——三年数据就是三年，再密的数据也换不来更多日历时间。")],-1)),(t(),i(l,null,{default:r(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Px%5B%22%E5%B7%B2%E5%AF%B9%E9%BD%90%E7%9A%84%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20SR%5B%22%E5%A4%8F%E6%99%AE%20IR%20Sortino%22%5D%0A%20%20SR%20--%3E%20SE%5B%22%E6%8A%BD%E6%A0%B7%E8%AF%AF%E5%B7%AE%20%E9%9A%8F%E6%97%A5%E5%8E%86%20T%22%5D%0A%20%20N%5B%22%E8%AF%95%E9%AA%8C%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20DSR%5B%22%E6%94%BE%E6%B0%94%22%5D%0A%20%20SE%20--%3E%20Dec%5B%22%E8%83%BD%E5%90%A6%E5%8C%BA%E5%88%86%E4%B8%A4%E5%8F%AA%E4%BA%A7%E5%93%81%22%5D%0A%20%20DSR%20--%3E%20Dec%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「最低可接受夏普」的营销数字。非正态、跳、制度断点让渐近公式偏乐观。要解释成交为何存在、时间戳如何定义，必须进入交易所技术：从撮合引擎架构开始。组合与策略进阶到此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>夏普/IR 是高方差估计量；均值几乎只随日历时间变准。</li><li>产品排序须带标准误与试验次数，不能靠点估计加杠杆。</li><li>会计对齐之后，剩下的是噪声与真正技能的分离。</li><li>出处：Merton, <em>JFE</em>, 1980；Lo, <em>FAJ</em>, 2002；Bailey and López de Prado 放气夏普。下一课：<a href="/quant/matching-engine-arch">撮合引擎架构</a>。</li></ul>',4))])}const b=A(d,[["render",m]]);export{q as __pageData,b as default};
